        // ХОЛСТ КАРТЫ АКТИВНОСТИ
        private int GetActivityLevelForDate(DateTime date)
        {
            int count = allScenarioAttempts.Count(p => p.StartedAt.HasValue && p.StartedAt.Value.Date == date.Date);
            if (count == 0) return 0;
            if (count == 1) return 1;
            if (count == 2) return 2;
            if (count == 3) return 3;
            return 4;
        }

